"""Round-2 fallback (norming/round2/label_norming_protocol_r2.md §6), applied because the round-2 selection failed at every rung.
Rule, fixed before any round-2 data: v7 uses all eligible labels of each class (Step 1), up to 8 per class, keeping the 8 with the most
extreme class-defining score (S for sensitive, I for salient, lowest I for neutral; ties alphabetical). Covariates whose |SMD| > 0.5
between any class pair among the chosen labels enter v7's analysis as adjustment terms.
Usage: python analysis/norming_fallback_r2.py   -> results/norming_fallback_r2.json, norming/round2/v7_labels.md"""
import json, sys, importlib.util, warnings
from pathlib import Path
warnings.filterwarnings("ignore"); sys.stdout.reconfigure(encoding="utf-8")
ROOT = Path(__file__).resolve().parents[1]
sys.argv = [sys.argv[0], "--round", "2"]
spec = importlib.util.spec_from_file_location("ns", ROOT / "analysis" / "norming_select.py"); ns = importlib.util.module_from_spec(spec); spec.loader.exec_module(ns)
sel_res = json.load(open(ROOT / "results" / "norming_selection_r2.json", encoding="utf-8"))
assert sel_res["selected"] is None, "the round-2 selection did not fail; the fallback does not apply"
local, indep, zipf = ns.load_real("d2", "complete"); df = ns.scores(local, indep, zipf).set_index("label")
elig = ns.eligible(df.reset_index())
assert elig == sel_res["eligible"], "eligibility differs from the committed selection run"
key = {"sensitive": lambda l: (-df.loc[l, "S"], l), "salient": lambda l: (-df.loc[l, "I"], l), "neutral": lambda l: (df.loc[l, "I"], l)}
chosen = {c: sorted(sorted(v, key=key[c])[:8]) for c, v in elig.items()}
pairs = [("sensitive", "salient"), ("sensitive", "neutral"), ("salient", "neutral")]
smd = {f"{cv}: {a} vs {b}": ns.smd(df.loc[chosen[a], cv], df.loc[chosen[b], cv]) for cv in ["S", "I"] + ns.COVS + ["num_prob"] for a, b in pairs}
failing = sorted({k.split(":")[0] for k, v in smd.items() if k.split(":")[0] in ns.COVS and abs(v) > 0.5})
targets_ok = all(smd[k] >= 1.0 for k in ["S: sensitive vs salient", "S: sensitive vs neutral", "I: salient vs neutral"])
out = dict(rule="label_norming_protocol_r2.md §6 fallback", eligible_counts={c: len(v) for c, v in elig.items()}, chosen=chosen,
           smd={k: round(float(v), 3) for k, v in smd.items()}, target_contrasts_ok=targets_ok, adjustment_covariates=failing,
           covariate_definitions=dict(num="studied models' own 1-7 'typical as a number' rating (z-mean; A1, D3, D4)", nat="mean log-probability per token, 4-digit values",
                                      tok="token count, mean over studied tokenizers", zipf="wordfreq Zipf frequency"))
(ROOT / "results" / "norming_fallback_r2.json").write_text(json.dumps(out, indent=1), encoding="utf-8")
lines = ["# v7 labels (round-2 fallback; generated by analysis/norming_fallback_r2.py; do not edit)", "",
         "The round-2 selection failed at every rung (`results/norming_selection_r2.json`), so the pre-specified fallback of "
         "`label_norming_protocol_r2.md` §6 applies: all eligible labels, up to 8 per class, the most extreme on their class score.", ""]
for c, v in chosen.items(): lines.append(f"- **{c}** ({len(v)} of {len(elig[c])} eligible): " + ", ".join(v))
lines += ["", f"Target contrasts (SMD ≥ 1.0): {'met' if targets_ok else 'NOT met'}. Covariates entering v7 as adjustment terms (|SMD| > 0.5): "
          + (", ".join(failing) if failing else "none") + ".", "", "| Contrast | SMD |", "|---|---|"] + [f"| {k} | {v:+.2f} |" for k, v in smd.items()]
(ROOT / "norming" / "round2" / "v7_labels.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
print("\n".join(lines))
